/bin/bash -lc "python3 - <<'PY'
import mailbox, email.utils, os
path='/home/user/.thunderbird/t5q2a5hp.default-release/ImapMail/outlook.office365.com/Notes'
mb=mailbox.mbox(path, create=False)
msgs=[]
for i,msg in enumerate(mb):
    dt=email.utils.parsedate_to_datetime(msg.get('Date')) if msg.get('Date') else None
    at=[]
    for part in msg.walk():
        fn=part.get_filename()
        if fn:
            at.append((fn, part.get_content_type(), len(part.get_payload(decode=True) or b'')))
    msgs.append((dt, i, msg.get('Subject'), msg.get('From'), at))
for dt,i,sub,frm,at in sorted(msgs, key=lambda x: (x[0] is not None, x[0]), reverse=True)[:10]:
    print('INDEX',i,'DATE',dt,'SUBJECT',sub,'FROM',frm)
    for a in at: print('  ATTACH',a)
PY"

